// a bold section head is a design change, not a preference.`,ai={icon:pt,footnote:ti,caption:ri,"section-head":()=>(0,y.jsxs)(y.Fragment,{children:[(0,y.jsx)(`p`,{className:`wgd-lead`,children:`The heading that opens a group of cards or rows on a panel ("Your day so far"). Larger and darker than everything under it, and that is its entire job.`}),(0,y.jsx)(K,{title:`Specimen`,children:(0,y.jsx)(V,{ground:`panel`,children:(0,y.jsxs)(`div`,{style:{minWidth:300},children:[(0,y.jsx)(`h2`,{className:`wg-sect`,style:{marginTop:0},children:`Your day so far`}),(0,y.jsx)(`p`,{className:`wg-footnote`,style:{textAlign:`start`,margin:0},children:`(the cards it introduces sit under it on the panel)`})]})})}),(0,y.jsx)(K,{title:`Anatomy`,children:(0,y.jsx)(U,{rows:[{part:`Text`,spec:`21, Medium, -1% tracking, --ink. Margin --space-16 above, --space-8 sides and below.`},{part:`Weight`,spec:`Medium (500) - the only emphasis weight in the system. Never bold.`}]})}),(0,y.jsx)(K,{title:`Behaviour`,children:(0,y.jsx)(W,{rows:[{state:`Rhythm`,rule:`The gap above a section head is the panel column rhythm ([D-030]): one --space-16 step, not an ad-hoc gap.`},{state:`Quiet alternative`,rule:`When a head would be too loud for what it labels, use a Caption instead.`}]})}),(0,y.jsx)(K,{title:`React Native`,children:(0,y.jsx)(G,{label:`wg/SectionHeading.tsx`,code:ii})})]}),tag:Fr,"tone-pill":Lr,"state-pill":zr,"status-pill":Vr,switch:Ze,progress:$e,"page-dots":tt,slider:rt,skeleton:Gr,"card-line":Ve,"code-box":ze,button:Ee,chip:Le,avatar:Ae,field:Ge,segmented:mr,"inline-link":Zr,"text-button":$r,"option-row":tr,"empty-state":Ue,"setting-row":gr,"setting-group":ot,"list-row":st,"module-row":hn,"tile-grid":Jr,"bento-tile":Yr,gallery:Ye,notice:Xn,"filter-rail":_t,"search-field":bt,"assistant-summary":xe,screen:Tr,panel:Er,"app-header":rr,"back-bar":ar,"onboarding-bar":sr,"tab-bar":Ar,sheet:br,"sheet-actions":xr,toast:Nr,"action-bar":ye,"screen-transition":ur,"not-connected":_n,"widget-cell":Kn,"w